            Some(format!("{prefix}.{name}").into())
        };
        for (key, alias) in self.data.type_aliases.iter_mut().filter(|(key, _)| direct(key)) {
            let params = self.data.type_alias_params.get(key);
            *alias = alias.rename_named(&|name: &str| qualified(params, name));
        }
        for (key, interface) in self.data.interfaces.iter_mut().filter(|(key, _)| direct(key)) {
            let params = self.data.interface_type_params.get(key);
            let rename = |name: &str| qualified(params, name);
            for prop in &mut interface.props {
                prop.collected_type = prop.collected_type.rename_named(&rename);
            }
            for extends in &mut interface.extends {
                *extends = extends.map_type_args(|arg| arg.rename_named(&rename));
                if let ExtendsRef::SameFile { name, .. } = extends
                    && let Some(renamed) = rename(name)
                {
                    *name = renamed;
                }
            }
        }
    }

    fn finish(mut self) -> SourceData {
        for (key, start) in std::mem::take(&mut self.body_result_keys) {
            if let (Some(result), Some(scope)) =
                (self.data.function_results.get_mut(&key), self.body_scopes.get(&start))
            {
                result.scope = scope.clone();
            }
        }
        for (key, name, params, scope) in std::mem::take(&mut self.pending_classes) {
            if self.data.interfaces.contains_key(&key) || self.data.type_aliases.contains_key(&key) {
                continue;
            }
            self.data.class_scopes.insert(key.clone(), scope.clone());
            self.data.interfaces.insert(
                key.clone(),
                crate::types::CollectedInterface {
                    scoped_key: key.clone(),
                    name,
                    scope,
                    file_path: self.file_path.clone(),
                    props: Vec::new(),
                    extends: Vec::new(),
                    description: String::new(),
                    tags: Default::default(),
                },
            );
            if !params.is_empty() {
                self.data.interface_type_params.insert(key, params);
            }
        }
        self.promote_function_aliases();
        self.promote_wrapper_calls();
        self.promote_identifier_aliases();
        self.promote_factory_calls();
        self.promote_reexported_imports();
        // Filtered by original identifier first, before any displayName rename
        // below can change what identifier a mapping currently answers to.
        if !self.aliased_away.is_empty() {
            // An exported base is public under its own name too (`export function Card`, `export const MemoCard =
            // memo(Card)`); only an implementation-only base is hidden behind its alias.
            let exported: rustc_hash::FxHashSet<&str> = self
                .data
                .exports
                .iter()
                .filter_map(|e| match e {
                    crate::types::LexedExport::LocalDeclaration { name, .. } => Some(name.as_str()),
                    _ => None,
                })
                .collect();
            let hidden: FxHashSet<CompactString> =
                self.aliased_away.iter().filter(|n| !exported.contains(n.as_str())).cloned().collect();
            self.data.component_mappings.retain(|m| !hidden.contains(m.component_name.as_str()));
        }
        let exports = self.component_exports();
        self.drop_functions_used_only_as_functions(&exports);
        for mapping in &mut self.data.component_mappings {
            mapping.exports = exports.get(mapping.component_name.as_str()).cloned().unwrap_or_default();
            for (start, end, defaults) in &self.body_defaults {
                if *start >= mapping.span_start && *end <= mapping.span_end {
                    for (name, default) in defaults {
                        mapping.param_defaults.entry(name.clone()).or_insert_with(|| default.clone());
                    }
                }
            }
            for (start, end, params) in &self.function_type_params {
                if *start >= mapping.span_start && *end <= mapping.span_end {
                    for param in params {
                        if !mapping.type_params.contains(param) {
                            mapping.type_params.push(param.clone());
                        }
                    }
                }
            }
        }
        for (obj_name, display_name) in self.pending_display_name_renames.drain(..) {
            if let Some(mapping) = self.data.component_mappings.iter_mut().find(|m| m.component_name == obj_name) {
                mapping.component_name = display_name;
            }
        }
        self.data
    }

    /// `import { A } from "./a"; export { A }` re-exports `A` exactly like `export { A } from "./a"`, and
    /// `import * as a from "./a"; export { a as A }` like `export * as A from "./a"`; barrels and bundled typings
    /// (radix-ui's) use both spellings, and only the second names a source file to follow.
    fn promote_reexported_imports(&mut self) {
        for (index, local) in std::mem::take(&mut self.pending_local_exports) {
            let Some(binding) = self.data.imports.iter().find(|imp| imp.local_name.as_str() == local) else { continue };
            let crate::types::LexedExport::LocalDeclaration { name, is_type_only, .. } = &self.data.exports[index]
            else {
                continue;
            };
            if binding.exported_name.as_str() == "*" {
                self.data.exports[index] = crate::types::LexedExport::ReExportNamespace {
                    namespace: name.clone(),
                    source_specifier: binding.specifier.clone(),
                };
                continue;
            }
            self.data.exports[index] = crate::types::LexedExport::ReExportNamed {
                local_name: name.clone(),
                source_name: binding.exported_name.to_string(),
                source_specifier: binding.specifier.clone(),
                is_type_only: *is_type_only || binding.is_type_only,
            };
        }
    }

    // ─── Import source specifier lookup ──────────────────────────────────────

    pub(super) fn find_import_specifier(&self, local_name: &str) -> Option<String> {
        self.data.imports.iter().find(|imp| imp.local_name.as_str() == local_name).map(|imp| imp.specifier.clone())
    }

    /// Whether `name` here can be React's (imported from React) or a global (not imported at all): an element-like
    /// type name imported from another module is that module's type.
    /// Which React API a call's callee names, by where it was imported from and not by what it is called:
    /// `forwardRef`, `React.forwardRef`, `R.forwardRef` for `import * as R from "react"`, and `import { forwardRef as fr }`
    /// all name the same one, while a `forwardRef` imported from another module is not React's. A name no import binds
    /// (the global `React`, or `const { forwardRef } = React`) is read as written.
    pub(super) fn react_api(&self, callee: &Expression<'_>) -> Option<ReactApi> {
        let import_of = |local: &str| self.data.imports.iter().find(|import| import.local_name.as_str() == local);
        match component::peel_expr(callee) {
            Expression::Identifier(id) => match import_of(id.name.as_str()) {
                Some(import) if is_react_module(&import.specifier) => {
                    ReactApi::of_export(import.exported_name.as_str())
                }
                Some(_) => None,
                None => ReactApi::of_export(id.name.as_str()),
            },
            Expression::StaticMemberExpression(member) => {
                let Expression::Identifier(object) = component::peel_expr(&member.object) else { return None };
                let api = ReactApi::of_export(member.property.name.as_str())?;
                match import_of(object.name.as_str()) {
                    Some(import)
                        if is_react_module(&import.specifier)
                            && matches!(import.exported_name.as_str(), "*" | "default") =>

