    /// Drop the component candidates that are not exported and are used only as functions: every reference is a call,
    /// or they take a second parameter (a ref) and are never rendered. Each is reported as a skipped candidate.
    pub(super) fn drop_functions_used_only_as_functions(
        &mut self,
        exported: &FxHashMap<CompactString, Vec<ComponentExport>>,
    ) {
        let mut dropped: Vec<(String, String, Span)> = Vec::new();
        for mapping in &self.data.component_mappings {
            let name = mapping.component_name.as_str();
            if exported.contains_key(name) {
                continue;
            }
            let uses = self.name_uses.get(name).copied().unwrap_or_default();
            let reason = if uses.calls > 0 && uses.references == uses.calls {
                "is only ever called as a function in this file, never rendered or passed on, so it is a helper"
            } else if self.takes_a_second_parameter.contains(name) && uses.rendered == 0 {
                "takes a second parameter (a ref) and is never rendered or passed to a component wrapper in this \
                 file, so it is a render callback"
            } else {
                continue;
            };
            dropped.push((name.to_owned(), reason.to_owned(), Span::new(mapping.span_start, mapping.span_end)));
        }
        for (name, reason, span) in dropped {
            self.data.component_mappings.retain(|m| m.component_name != name);
            self.record_skip(DiagnosticCode::SkippedCandidate, format!("'{name}' {reason}, not a component"), span);
        }
    }
}
    let skipped: Vec<&str> = data
        .diagnostics
        .iter()
        .filter(|d| d.message.ends_with("not a component"))
        .map(|d| d.message.as_str())
        .collect();
    assert_eq!(
        skipped,
        vec![
            "'IndexedAccess' is only ever called as a function in this file, never rendered or passed on, so it is \
             a helper, not a component",
            "'DropWrapper' takes a second parameter (a ref) and is never rendered or passed to a component wrapper in \
             this file, so it is a render callback, not a component",
        ]
    );
}

#[test]
fn a_component_records_the_exports_its_module_has_for_it_or_for_the_export_it_is_attached_to() {
    let exports = |path: &str, source: &str| -> Vec<(String, Vec<String>)> {
        let data = parse_file(Utf8Path::new(path), source);
        let mut found: Vec<(String, Vec<String>)> = data
            .component_mappings
            .iter()
            .inspect(|m| assert_eq!(m.exported(), !m.exports.is_empty()))
            .map(|m| (m.component_name.to_string(), m.exports.iter().map(ToString::to_string).collect()))
            .collect();
        found.sort_unstable();
        found
    };
    let source = r#"
        interface P { label: string }
        export function Direct(props: P) { return <b />; }
        export const Arrow = (props: P) => <i />;
        function Renamed(props: P) { return <u />; }
        export { Renamed as Public };
        function Defaulted(props: P) { return <s />; }
        export default Defaulted;
        function Item(props: P) { return <li />; }
        Direct.Item = Item;
        function Header(props: P) { return <h1 />; }
        export const Card = Object.assign((props: P) => <div />, { Header });
        function MenuRoot(props: P) { return <ul />; }
        function MenuItem(props: P) { return <li />; }
        export const Menu = Object.assign(MenuRoot, { Item: MenuItem });
        function Internal(props: P) { return <p />; }
        function Orphan(props: P) { return <em />; }
        Internal.Orphan = Orphan;
        const shown = <><Internal label="x" /><Orphan label="y" /></>;
    "#;
    assert_eq!(
        exports("/test/exports.tsx", source),
        named(&[
            ("Arrow", &["Arrow"]),
            ("Card", &["Card"]),
            ("Defaulted", &["default"]),
            ("Direct", &["Direct"]),
            ("Header", &["Card.Header"]),
            ("Internal", &[]),
            ("Item", &["Direct.Item"]),
            ("Menu", &["Menu"]),
            ("MenuItem", &["Menu.Item"]),
            ("Orphan", &[]),
            ("Renamed", &["Public"]),
        ])
    );
    assert_eq!(
        exports("/test/fancy-badge.tsx", "export default function (props: { tone: string }) { return <span />; }"),
        named(&[("FancyBadge", &["default"])])
    );
    // The module's default is `Menu`, so `Item` is `default.Item`, and never the default itself; one function under two
    // names has both; sub-components attached to each other in a cycle end at the first path that reaches them.
    let source = r#"
        interface P { label: string }
        function Item(props: P) { return <li />; }
        function Menu(props: P) { return <ul />; }
        Menu.Item = Item;
        export default Menu;
        function Ping(props: P) { return <i />; }
        function Pong(props: P) { return <u />; }
        Ping.Pong = Pong;
        Pong.Ping = Ping;
        export { Ping as Game };
    "#;
    assert_eq!(
        exports("/test/menu.tsx", source),
        named(&[("Item", &["default.Item"]), ("Menu", &["default"]), ("Ping", &["Game"]), ("Pong", &["Game.Pong"]),])
    );
    assert_eq!(
        exports(
            "/test/twice.tsx",
            "export function Twice(props: { a: string }) { return <b />; } export default Twice;"
        ),
        named(&[("Twice", &["Twice", "default"])])
    );
}

